# Special config values keep their path fallback.
_choice_config() {
    printf 'NONE\nNORC\n'
    _argc_util_comp_path
}

# Running servers listen on sockets named $XDG_RUNTIME_DIR/nvim.*.
_choice_server() {
    local dir="${XDG_RUNTIME_DIR:-/tmp}" socket
    for socket in "$dir"/nvim.*; do
        if [[ -S "$socket" ]]; then
            printf '%s\n' "$socket"
        fi
    done
    return 0
}

# Tag names from the nearest tags file, described by their file path.
_choice_tag() {
    local tags
    tags="$(_argc_util_path_search_parent tags)"
    [[ -n $tags ]] || return 0
    gawk -F '\t' '!/^!_TAG_/ && NF >= 2 { print $1 "\t" $2 }' "$tags"
}
